        conn.execute("PRAGMA query_only=ON")
    else:
        conn.execute("PRAGMA synchronous=NORMAL")
    try:
        yield conn
        if readonly:
            pass          # nothing to commit; mode=ro would refuse anyway
        elif not dry_run:
            conn.commit()
        else:
            conn.rollback()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


